using System.IO;
using System.Numerics;
using NiflySharp;
using NiflySharp.Blocks;
namespace FaceAssets;
// Shared NIF guard and parser; no Facial Studio UI or facial data changes.
public static class NifHierarchyReader {
 public sealed record Node(string Name,int Parent,Vector3 Translation,Quaternion Rotation,Vector3 Scale);
 public static Node[] Read(string path){using var input=NifGuard.Open(path);var f=new NifFile();if(f.Load(input)!=0||!f.Valid||f.HasUnknownBlocks)throw new InvalidDataException("Unsupported/damaged Skyrim NIF.");var nodes=f.Blocks.OfType<NiNode>().ToList();if(nodes.Count==0||nodes.Count>4096)throw new InvalidDataException("NIF has no NiNode skeleton, or exceeds 4096 bones.");var indexes=nodes.Select((n,i)=>(n,i)).ToDictionary(x=>x.n,x=>x.i);var seenParents=new Dictionary<NiNode,NiNode>();foreach(var parent in nodes)foreach(int index in parent.Children.Indices){if(index<0)continue;if(index>=f.Blocks.Count)throw new InvalidDataException("NIF child index out of range.");if(f.Blocks[index] is NiNode child&&!seenParents.TryAdd(child,parent))throw new InvalidDataException("A skeleton NiNode has duplicate/multiple parents: "+child.Name.String);}var result=new List<Node>();foreach(var n in nodes){var r=n.Rotation;var m=new Matrix4x4(r.M11,r.M21,r.M31,0,r.M12,r.M22,r.M32,0,r.M13,r.M23,r.M33,0,0,0,0,1);var parent=f.GetParentNode(n);if(parent!=null&&!indexes.ContainsKey(parent))throw new InvalidDataException("NIF parent is not a supported NiNode.");float gain=new Vector3(m.M11,m.M12,m.M13).Length();if(!float.IsFinite(gain)||gain<.000001)throw new InvalidDataException("Invalid NIF bone transform: "+n.Name.String);m.M11/=gain;m.M12/=gain;m.M13/=gain;m.M21/=gain;m.M22/=gain;m.M23/=gain;m.M31/=gain;m.M32/=gain;m.M33/=gain;if(!Orthogonal(m))throw new InvalidDataException("NIF rotation is not orthonormal: "+n.Name.String+" / "+m.ToString());float scale=n.Scale*gain;if(m.GetDeterminant()<0){m.M11=-m.M11;m.M12=-m.M12;m.M13=-m.M13;m.M21=-m.M21;m.M22=-m.M22;m.M23=-m.M23;m.M31=-m.M31;m.M32=-m.M32;m.M33=-m.M33;scale=-scale;}result.Add(new(n.Name.String,parent==null?-1:indexes[parent],n.Translation,Quaternion.CreateFromRotationMatrix(m),new Vector3(scale)));}return result.ToArray();}
 static bool Orthogonal(Matrix4x4 m){var x=new Vector3(m.M11,m.M12,m.M13);var y=new Vector3(m.M21,m.M22,m.M23);var z=new Vector3(m.M31,m.M32,m.M33);return Math.Abs(x.LengthSquared()-1)<.002&&Math.Abs(y.LengthSquared()-1)<.002&&Math.Abs(z.LengthSquared()-1)<.002&&Math.Abs(Vector3.Dot(x,y))<.002&&Math.Abs(Vector3.Dot(x,z))<.002&&Math.Abs(Vector3.Dot(y,z))<.002&&Math.Abs(Math.Abs(m.GetDeterminant())-1)<.002;}
}

